def compute_order_amount(on_hand_inventory, pipeline_orders):
    base_stock = 520  # OPT_PARAM: {'initial': 520, 'min': 100, 'max': 2000, 'type': 'float'}
    max_order = 140   # OPT_PARAM: {'initial': 140, 'min': 1, 'max': 400, 'type': 'float'}
    current_position = on_hand_inventory + sum(pipeline_orders)
    order_amount = max(0, int(round(base_stock - current_position)))
    if order_amount > int(max_order):
        order_amount = int(max_order)
    return order_amount
